 private static final String HOME="https://retro.jivagames.net/";
 private WebView game; private DisplayManager displays; private Companion companion; private boolean running; private TextView pointer; private float px=500,py=350,stickX,stickY; private long downAt,lastTriggerAt;private boolean leftTrigger,rightTrigger;private int selectedSpell=-1;
 private final Handler handler=new Handler();
 private final Runnable cursorTick=new Runnable(){public void run(){if(!running)return;if(Math.abs(stickX)>.18f||Math.abs(stickY)>.18f){px=Math.max(1,Math.min(game.getWidth()-2,px+stickX*17));py=Math.max(1,Math.min(game.getHeight()-2,py+stickY*17));showPointer();}handler.postDelayed(this,16);}};
 private void showPointer(){if(pointer==null)return;pointer.setVisibility(View.VISIBLE);pointer.setX(px-15);pointer.setY(py-15);}
 private boolean shortcut(KeyEvent e){int mapped;switch(e.getKeyCode()){case KeyEvent.KEYCODE_BUTTON_X:mapped=KeyEvent.KEYCODE_I;break;case KeyEvent.KEYCODE_BUTTON_Y:mapped=KeyEvent.KEYCODE_Q;break;case KeyEvent.KEYCODE_BUTTON_L1:mapped=KeyEvent.KEYCODE_C;break;case KeyEvent.KEYCODE_BUTTON_R1:mapped=KeyEvent.KEYCODE_S;break;case KeyEvent.KEYCODE_BUTTON_B:case KeyEvent.KEYCODE_BUTTON_START:mapped=KeyEvent.KEYCODE_ESCAPE;break;default:return false;}game.dispatchKeyEvent(new KeyEvent(e.getDownTime(),e.getEventTime(),e.getAction(),mapped,e.getRepeatCount()));return true;}
 private void cycleSpell(int direction){if(companion==null)return;JSONArray a=companion.latest.optJSONArray("spells");if(a==null||a.length()==0)return;selectedSpell=(selectedSpell+direction+a.length())%a.length();JSONObject spell=a.optJSONObject(selectedSpell);if(spell!=null){activate(spell.optString("id"));android.widget.Toast.makeText(this,spell.optString("name"),android.widget.Toast.LENGTH_SHORT).show();}}
 private void triggerSpell(int direction){long now=SystemClock.uptimeMillis();if(now-lastTriggerAt>=220){lastTriggerAt=now;cycleSpell(direction);}}
 @Override public boolean dispatchGenericMotionEvent(MotionEvent e){if((e.getSource()&InputDevice.SOURCE_JOYSTICK)==InputDevice.SOURCE_JOYSTICK&&e.getAction()==MotionEvent.ACTION_MOVE){stickX=e.getAxisValue(MotionEvent.AXIS_X);stickY=e.getAxisValue(MotionEvent.AXIS_Y);boolean left=Math.max(e.getAxisValue(MotionEvent.AXIS_LTRIGGER),e.getAxisValue(MotionEvent.AXIS_BRAKE))>.6f,right=Math.max(e.getAxisValue(MotionEvent.AXIS_RTRIGGER),e.getAxisValue(MotionEvent.AXIS_GAS))>.6f;if(left&&!leftTrigger)triggerSpell(-1);if(right&&!rightTrigger)triggerSpell(1);leftTrigger=left;rightTrigger=right;return true;}return super.dispatchGenericMotionEvent(e);}
 @Override public boolean dispatchKeyEvent(KeyEvent e){int code=e.getKeyCode();boolean controller=(e.getSource()&InputDevice.SOURCE_GAMEPAD)==InputDevice.SOURCE_GAMEPAD||(e.getSource()&InputDevice.SOURCE_JOYSTICK)==InputDevice.SOURCE_JOYSTICK||(e.getSource()&InputDevice.SOURCE_DPAD)==InputDevice.SOURCE_DPAD;if(controller){if(shortcut(e))return true;if(code==KeyEvent.KEYCODE_BUTTON_L2||code==KeyEvent.KEYCODE_BUTTON_R2){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0)triggerSpell(code==KeyEvent.KEYCODE_BUTTON_R2?1:-1);return true;}if(code==KeyEvent.KEYCODE_BUTTON_A){showPointer();long now=SystemClock.uptimeMillis();if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){downAt=now;game.dispatchTouchEvent(MotionEvent.obtain(downAt,now,MotionEvent.ACTION_DOWN,px,py,0));}else if(e.getAction()==KeyEvent.ACTION_UP&&downAt!=0){game.dispatchTouchEvent(MotionEvent.obtain(downAt,now,MotionEvent.ACTION_UP,px,py,0));downAt=0;}return true;}if(e.getAction()==KeyEvent.ACTION_DOWN){switch(code){case KeyEvent.KEYCODE_DPAD_LEFT:px-=28;break;case KeyEvent.KEYCODE_DPAD_RIGHT:px+=28;break;case KeyEvent.KEYCODE_DPAD_UP:py-=28;break;case KeyEvent.KEYCODE_DPAD_DOWN:py+=28;break;default:return super.dispatchKeyEvent(e);}px=Math.max(1,Math.min(game.getWidth()-2,px));py=Math.max(1,Math.min(game.getHeight()-2,py));showPointer();return true;}}return super.dispatchKeyEvent(e);}
 private final DisplayManager.DisplayListener listener=new DisplayManager.DisplayListener(){public void onDisplayAdded(int id){showCompanion();} public void onDisplayRemoved(int id){showCompanion();} public void onDisplayChanged(int id){showCompanion();}};
 private final Runnable poll=new Runnable(){public void run(){
  if(!running)return;
  if(game!=null && game.getUrl()!=null && game.getUrl().startsWith(HOME)) game.evaluateJavascript("(function(){const q=s=>document.querySelector(s),attr=(s,a)=>q(s)?.getAttribute(a)||'',txt=s=>(q(s)?.innerText||'').trim().slice(0,600),make=(x,name)=>{let y=[...x.querySelectorAll('*')].find(z=>getComputedStyle(z).backgroundImage!=='none'),s=y?getComputedStyle(y):null;return {id:x.getAttribute('data-testid'),name:name,image:s?s.backgroundImage:'',position:s?s.backgroundPosition:'',size:s?s.backgroundSize:'',width:y?y.getBoundingClientRect().width:0,height:y?y.getBoundingClientRect().height:0}},slots=[...document.querySelectorAll('[data-testid^=spell-slot-]')].filter(x=>x.title&&!/^Emplacement/.test(x.title)).map(x=>make(x,x.title)),bag=[...document.querySelectorAll('[data-testid=window-inventory] [data-testid^=bag-]')].map(x=>make(x,(x.querySelector('.sr-only')?.textContent||'Objet')+(x.querySelector('.item-slot-qty')?' ×'+x.querySelector('.item-slot-qty').textContent:''))),buttons=[...document.querySelectorAll('button')].filter(x=>x.getClientRects().length),combat=buttons.some(x=>/^(Fin du tour|Abandonner|Prêt)$/i.test((x.innerText||'').trim()));return JSON.stringify({hp:attr('[data-testid=hp-heart]','aria-label'),ap:attr('[data-testid=ap-badge]','aria-label'),mp:attr('[data-testid=mp-badge]','aria-label'),inventory:attr('[data-testid=menu-inventory]','aria-pressed')==='true',quests:attr('[data-testid=menu-quests]','aria-pressed')==='true',questList:txt('[data-testid=window-quests] .qs-list'),questSteps:txt('[data-testid=window-quests] .qs-steps'),item:txt('[data-testid=item-viewer] .inv-viewer-id'),effects:txt('[data-testid=item-viewer] .inv-viewer-infos'),pods:attr('[role=progressbar][aria-label^=Pods]','aria-label'),combat:combat,spells:slots,bag:bag});})()", value->{try{String decoded=new JSONArray("["+value+"]").optString(0,"{}");JSONObject data=new JSONObject(decoded);if(companion!=null)companion.update(data);}catch(Exception ignored){}});
  handler.postDelayed(this,1500);
 }};
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);game=new WebView(this);game.getSettings().setJavaScriptEnabled(true);game.getSettings().setDomStorageEnabled(true);game.getSettings().setMediaPlaybackRequiresUserGesture(false);game.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){String h=request.getUrl().getHost();return h==null||!h.equalsIgnoreCase("retro.jivagames.net");}});FrameLayout frame=new FrameLayout(this);frame.addView(game);pointer=new TextView(this);pointer.setText("✥");pointer.setTextSize(26);pointer.setTextColor(Color.WHITE);pointer.setShadowLayer(4,1,1,Color.BLACK);pointer.setVisibility(View.GONE);pointer.setClickable(false);frame.addView(pointer,new FrameLayout.LayoutParams(-2,-2));setContentView(frame);game.loadUrl(HOME);displays=(DisplayManager)getSystemService(DISPLAY_SERVICE);displays.registerDisplayListener(listener,handler);}
 @Override protected void onStart(){super.onStart();running=true;showCompanion();handler.post(poll);handler.post(cursorTick);}
 @Override protected void onResume(){super.onResume();showCompanion();}
 @Override protected void onStop(){running=false;handler.removeCallbacks(poll);handler.removeCallbacks(cursorTick);stickX=stickY=0;closeCompanion();super.onStop();}
 @Override protected void onDestroy(){displays.unregisterDisplayListener(listener);closeCompanion();game.destroy();super.onDestroy();}
 @Override public void onBackPressed(){if(game.canGoBack())game.goBack();else super.onBackPressed();}
 private void activate(String id){if(game==null||game.getUrl()==null||!game.getUrl().startsWith(HOME))return;String js;if(id.equals("end"))js="[...document.querySelectorAll('button')].find(x=>x.getClientRects().length && /^(Fin du tour|Prêt)$/i.test((x.innerText||'').trim()))?.click()";else if(id.matches("spell-slot-[0-9]+")||id.matches("bag-[0-9]+")||id.matches("menu-(inventory|quests|spells|stats)"))js="document.querySelector('[data-testid="+id+"]')?.click()";else return;game.evaluateJavascript(js,null);}
 private void closeCompanion(){if(companion!=null){companion.dismiss();companion=null;}}
 private void showCompanion(){if(!running||displays==null)return;Display target=null;for(Display d:displays.getDisplays(DisplayManager.DISPLAY_CATEGORY_PRESENTATION))if(d.getDisplayId()!=getWindowManager().getDefaultDisplay().getDisplayId()){target=d;break;}if(target==null){closeCompanion();return;}if(companion!=null&&companion.getDisplay().getDisplayId()==target.getDisplayId())return;closeCompanion();try{companion=new Companion(this,target);companion.show();}catch(WindowManager.InvalidDisplayException e){companion=null;}}
 private final class Companion extends Presentation {
  private final int ink=Color.rgb(72,65,50),muted=Color.rgb(111,101,78),accent=Color.rgb(201,91,18);private LinearLayout root,nav,spellRow,actions;private TextView status,body,hpText,apText,mpText;private JSONObject latest=new JSONObject();private String mode="Auto",spellKey="",actionKey="";private final HashMap<String,Bitmap> spriteCache=new HashMap<>();
  Companion(Context c,Display d){super(c,d);}
  TextView label(String text,int size,int color){TextView t=new TextView(getContext());t.setText(text);t.setTextSize(size);t.setTextColor(color);return t;}
  GradientDrawable shape(int color,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(18);d.setStroke(2,stroke);return d;}
  void gameIcon(ImageView image,String asset){new Thread(()->{HttpURLConnection c=null;try{URL u=new URL(HOME+"assets-build/ui/"+asset);c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(5000);c.setReadTimeout(5000);String cookie=CookieManager.getInstance().getCookie(HOME);if(cookie!=null)c.setRequestProperty("Cookie",cookie);if(c.getResponseCode()==200){android.graphics.Bitmap bmp=BitmapFactory.decodeStream(c.getInputStream());if(bmp!=null)handler.post(()->image.setImageBitmap(bmp));}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}},"jiva-icon").start();}
  float[] numbers(String text){java.util.regex.Matcher m=java.util.regex.Pattern.compile("-?[0-9]+(?:\\.[0-9]+)?").matcher(text);float[] v=new float[2];int n=0;while(m.find()&&n<2)v[n++]=Float.parseFloat(m.group());return v;}
  void spellIcon(ImageView image,JSONObject spell){String css=spell.optString("image");java.util.regex.Matcher match=java.util.regex.Pattern.compile("url\\([\"']?(.*?)[\"']?\\)").matcher(css);if(!match.find())return;String path=match.group(1);if(path.startsWith("/"))path=HOME.substring(0,HOME.length()-1)+path;final String url=path;if(!url.startsWith(HOME+"assets-build/"))return;float[] pos=numbers(spell.optString("position")),size=numbers(spell.optString("size"));float w=(float)spell.optDouble("width",0),h=(float)spell.optDouble("height",0);if(size[0]<=0||size[1]<=0||w<=0||h<=0)return;new Thread(()->{try{Bitmap source; synchronized(spriteCache){source=spriteCache.get(url);}if(source==null){HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(5000);c.setReadTimeout(5000);String cookie=CookieManager.getInstance().getCookie(HOME);if(cookie!=null)c.setRequestProperty("Cookie",cookie);if(c.getResponseCode()!=200){c.disconnect();return;}source=BitmapFactory.decodeStream(c.getInputStream());c.disconnect();if(source==null)return;synchronized(spriteCache){spriteCache.put(url,source);}}float sx=source.getWidth()/size[0],sy=source.getHeight()/size[1];int x=Math.max(0,Math.round(-pos[0]*sx)),y=Math.max(0,Math.round(-pos[1]*sy));int cw=Math.min(source.getWidth()-x,Math.max(1,Math.round(w*sx))),ch=Math.min(source.getHeight()-y,Math.max(1,Math.round(h*sy)));if(cw>0&&ch>0){Bitmap icon=Bitmap.createBitmap(source,x,y,cw,ch);handler.post(()->image.setImageBitmap(icon));}}catch(Exception ignored){}},"jiva-spell-icon").start();}
  void rebuildSpells(JSONArray spells){String key=spells==null?"":spells.toString();if(key.equals(spellKey))return;spellKey=key;spellRow.removeAllViews();if(spells==null)return;for(int i=0;i<Math.min(50,spells.length());i++){JSONObject s=spells.optJSONObject(i);if(s==null)continue;String id=s.optString("id"),name=s.optString("name");LinearLayout cell=new LinearLayout(getContext());cell.setOrientation(1);cell.setGravity(android.view.Gravity.CENTER);cell.setPadding(4,4,4,4);cell.setBackground(shape(Color.rgb(245,242,220),Color.rgb(177,165,126)));ImageView icon=new ImageView(getContext());cell.addView(icon,new LinearLayout.LayoutParams(58,58));spellIcon(icon,s);TextView caption=label(name,9,ink);caption.setGravity(android.view.Gravity.CENTER);caption.setMaxLines(2);caption.setEllipsize(android.text.TextUtils.TruncateAt.END);cell.addView(caption);cell.setContentDescription(name);cell.setOnClickListener(v->activate(id));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(170,150);p.setMargins(3,0,3,0);spellRow.addView(cell,p);}}
  void actionButton(String text,String id,String icon){LinearLayout b=new LinearLayout(getContext());b.setOrientation(0);b.setGravity(android.view.Gravity.CENTER);b.setBackground(shape(Color.rgb(245,242,220),Color.rgb(177,165,126)));if(icon!=null){ImageView image=new ImageView(getContext());b.addView(image,new LinearLayout.LayoutParams(46,46));gameIcon(image,icon);}TextView label=label("  "+text,13,ink);b.addView(label);b.setContentDescription(text);b.setOnClickListener(v->activate(id));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,84,1);p.setMargins(3,0,3,0);actions.addView(b,p);}
  @Override protected void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);root=new LinearLayout(getContext());root.setOrientation(1);root.setPadding(28,24,28,24);root.setBackgroundColor(Color.rgb(221,219,191));setContentView(root);
   LinearLayout heading=new LinearLayout(getContext());heading.setGravity(android.view.Gravity.CENTER_VERTICAL);root.addView(heading);ImageView emblem=new ImageView(getContext());heading.addView(emblem,new LinearLayout.LayoutParams(70,70));gameIcon(emblem,"UI_BannerBookIcon.webp");LinearLayout headingText=new LinearLayout(getContext());headingText.setOrientation(1);headingText.setPadding(12,0,0,0);heading.addView(headingText);TextView over=label("JIVA  ·  CARNET DU VOYAGEUR",13,accent);headingText.addView(over);TextView title=label("Compagnon",30,ink);title.setTypeface(android.graphics.Typeface.SERIF,1);headingText.addView(title);status=label("En attente du jeu",14,muted);root.addView(status);
   LinearLayout hud=new LinearLayout(getContext());hud.setGravity(android.view.Gravity.CENTER_VERTICAL);hud.setPadding(0,8,0,8);root.addView(hud);ImageView heart=new ImageView(getContext());heart.setImageResource(R.drawable.heart);hud.addView(heart,new LinearLayout.LayoutParams(52,52));hpText=label(" — ",17,ink);hud.addView(hpText);ImageView star=new ImageView(getContext());hud.addView(star,new LinearLayout.LayoutParams(43,43));gameIcon(star,"Star.webp");apText=label(" — ",17,ink);hud.addView(apText);ImageView mpIcon=new ImageView(getContext());hud.addView(mpIcon,new LinearLayout.LayoutParams(43,43));gameIcon(mpIcon,"IconMP.webp");mpText=label(" — ",17,ink);hud.addView(mpText);HorizontalScrollView strip=new HorizontalScrollView(getContext());strip.setHorizontalScrollBarEnabled(false);root.addView(strip);spellRow=new LinearLayout(getContext());strip.addView(spellRow);actions=new LinearLayout(getContext());actions.setPadding(0,8,0,4);root.addView(actions);
   ScrollView scroll=new ScrollView(getContext());root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body=label("Connecte-toi au jeu pour afficher les informations disponibles.",17,ink);body.setLineSpacing(7,1.05f);scroll.addView(body);render();}
  void update(JSONObject d){latest=d;render();}
  void render(){if(body==null)return;String hp=latest.optString("hp"),ap=latest.optString("ap"),mp=latest.optString("mp");boolean present=!hp.isEmpty(),combat=latest.optBoolean("combat");String selected=combat?"Combat":latest.optBoolean("quests")?"Quêtes":latest.optBoolean("inventory")?"Inventaire":"Exploration";status.setText(present?"●  "+selected:"○  En attente du jeu");hpText.setText(present?"  "+hp.replace("Points de vie ","")+"     ":" —     ");apText.setText(present?"  "+ap.replace("Points d'action : ","")+"     ":" —     ");mpText.setText(present?"  "+mp.replace("Points de mouvement : ",""):" — ");rebuildSpells(latest.optJSONArray(selected.equals("Inventaire")?"bag":"spells"));String key=present+":"+combat;if(!key.equals(actionKey)){actionKey=key;actions.removeAllViews();if(present){actionButton("Inventaire","menu-inventory","UI_BannerInventoryIcon.webp");actionButton("Quêtes","menu-quests","UI_BannerBookIcon.webp");if(combat)actionButton("Fin du tour / Prêt","end",null);}}
   StringBuilder out=new StringBuilder();if(!present){out.append("Connecte-toi et entre dans le jeu.");body.setText(out.toString());return;}java.util.regex.Matcher life=java.util.regex.Pattern.compile("(\\d+)\\D+(\\d+)").matcher(hp);if(life.find()){int current=Integer.parseInt(life.group(1)),max=Integer.parseInt(life.group(2));if(max>0&&current*100/max<=35)out.append("⚠ Vie basse : pense à te soigner.\n\n");}
   if(combat){float[] a=numbers(ap),m=numbers(mp);if(a[0]<=0&&m[0]>0)out.append("Plus de PA : tu peux encore te déplacer si une case est accessible.\n\n");else if(a[0]<=0&&m[0]<=0)out.append("Plus de PA ni de PM : termine ton tour si tu n'as plus d'action à faire.\n\n");else out.append("Sélectionne un sort, puis sa cible. Vérifie sa portée et la ligne de vue.\n\n");out.append("L2 / R2 : choisir un sort");}
   else if(selected.equals("Quêtes")){String list=latest.optString("questList"),steps=latest.optString("questSteps");out.append(list.isEmpty()?"Ouvre ton journal pour voir les objectifs.":list);if(!steps.isEmpty())out.append("\n\n").append(steps);}else if(selected.equals("Inventaire")){String pods=latest.optString("pods"),item=latest.optString("item"),effects=latest.optString("effects");if(!pods.isEmpty())out.append(pods).append("\n\n");if(!item.isEmpty())out.append(item).append("\n").append(effects);else out.append("Choisis un objet ci-dessus pour voir ses caractéristiques.");}else out.append("L2 / R2 : choisir un sort    •    X : inventaire    •    Y : quêtes");body.setText(out.toString());}
 }
